/**
 * Lightweight event payload validation for Enterprise Q1 Active spine contracts.
 * No external schema library — pure TS guards (shared-kernel keeps zero extra deps).
 */

export type ValidateResult = { ok: true } | { ok: false; errors: string[] };

function reqStr(v: unknown, path: string, errors: string[]): void {
  if (typeof v !== 'string' || !v.trim()) errors.push(`${path}: required non-empty string`);
}

function optStr(v: unknown, path: string, errors: string[]): void {
  if (v !== undefined && v !== null && typeof v !== 'string') {
    errors.push(`${path}: expected string`);
  }
}

function reqNum(v: unknown, path: string, errors: string[]): void {
  if (typeof v !== 'number' || Number.isNaN(v)) errors.push(`${path}: required number`);
}

function isObj(v: unknown): v is Record<string, unknown> {
  return typeof v === 'object' && v !== null && !Array.isArray(v);
}

/** Active spine event type names (Q1 contract set). */
export const ACTIVE_SPINE_EVENTS = [
  'plm.bom.released.v2',
  'plm.eco.approved.v1',
  'pm.material.requested.v1',
  'pm.project.released.v1',
  'inventory.reservation.created.v1',
  'inventory.reservation.released.v1',
  'inv.stock.out.v1',
  'mes.production.recorded.v1',
  'mes.workorder.completed.v1',
  'proc.purchaseorder.created.v1',
  'proc.purchaseorder.approved.v1',
  'proc.material.received.v1',
] as const;

export type ActiveSpineEvent = (typeof ACTIVE_SPINE_EVENTS)[number];

export function validatePlmBomReleasedV2(payload: unknown): ValidateResult {
  const errors: string[] = [];
  if (!isObj(payload)) return { ok: false, errors: ['payload: must be object'] };
  reqStr(payload.bomVersionId, 'bomVersionId', errors);
  reqStr(payload.itemId, 'itemId', errors);
  reqStr(payload.revision, 'revision', errors);
  if (!Array.isArray(payload.components)) {
    errors.push('components: required array');
  } else {
    payload.components.forEach((c, i) => {
      if (!isObj(c)) {
        errors.push(`components[${i}]: must be object`);
        return;
      }
      reqStr(c.bomComponentId, `components[${i}].bomComponentId`, errors);
      reqStr(c.childItemId, `components[${i}].childItemId`, errors);
      reqNum(c.quantity, `components[${i}].quantity`, errors);
    });
  }
  return errors.length ? { ok: false, errors } : { ok: true };
}

export function validatePlmEcoApprovedV1(payload: unknown): ValidateResult {
  const errors: string[] = [];
  if (!isObj(payload)) return { ok: false, errors: ['payload: must be object'] };
  reqStr(payload.ecoId, 'ecoId', errors);
  reqStr(payload.ecoNumber, 'ecoNumber', errors);
  if (payload.affectedBomVersionIds !== undefined && !Array.isArray(payload.affectedBomVersionIds)) {
    errors.push('affectedBomVersionIds: expected array');
  }
  return errors.length ? { ok: false, errors } : { ok: true };
}

